<?php require_once __DIR__.'/../lib/helpers.php'; require_login(); $conn=db(); $from=$_GET['from']; $to=$_GET['to']; $q=$conn->query("SELECT k.nama, t.tanggal, COUNT(ti.id) jml, IFNULL(SUM(j.total_tagih),0) tagih,(SELECT IFNULL(SUM(nominal),0) FROM ksp_kas WHERE ref_table='ksp_tagih_harian' AND ref_id=t.id) setoran FROM ksp_tagih_harian t JOIN ksp_kolektor k ON k.id=t.kolektor_id LEFT JOIN ksp_tagih_item ti ON ti.tagih_id=t.id LEFT JOIN ksp_jadwal_angsuran j ON j.id=ti.jadwal_id WHERE t.tanggal BETWEEN '".$conn->real_escape_string($from)."' AND '".$conn->real_escape_string($to)."' GROUP BY t.id ORDER BY t.tanggal DESC"); ?><!doctype html><html><head><meta charset='utf-8'><title>Laporan Kolektor</title><style>@media print{@page{size:A4;margin:12mm}} body{font-family:Arial;font-size:11pt} table{width:100%;border-collapse:collapse} th,td{border:1px solid #333;padding:6px 8px}</style></head><body onload='window.print()'><h3>Performa Kolektor (<?php echo htmlspecialchars($from); ?> s/d <?php echo htmlspecialchars($to); ?>)</h3><table><thead><tr><th>Kolektor</th><th>Tanggal</th><th>Item</th><th>Tagih</th><th>Setoran</th></tr></thead><tbody><?php $sum=0;$sset=0; while($r=$q->fetch_assoc()): $sum+=$r['tagih']; $sset+=$r['setoran']; ?><tr><td><?php echo htmlspecialchars($r['nama']); ?></td><td><?php echo htmlspecialchars($r['tanggal']); ?></td><td><?php echo (int)$r['jml']; ?></td><td>Rp <?php echo rupiah($r['tagih']); ?></td><td>Rp <?php echo rupiah($r['setoran']); ?></td></tr><?php endwhile; ?><tr><td colspan='3' style='text-align:right'><b>Total</b></td><td><b>Rp <?php echo rupiah($sum); ?></b></td><td><b>Rp <?php echo rupiah($sset); ?></b></td></tr></tbody></table></body></html>